$adb='E:\Codex\tools\android-sdk\platform-tools\adb.exe'
function Focus(){ return ((& $adb shell dumpsys window)-join "`n") -match 'mCurrentFocus=.*com\.xiaoshouji\.app' }
function Dump($name){ & $adb shell uiautomator dump "/sdcard/$name.xml" 2>$null | Out-Null; return (& $adb shell cat "/sdcard/$name.xml") }
function Has($xml,$text){ return $xml -match ('text="'+[regex]::Escape($text)+'"') }
function TapText($xml,$text,$bottom=$false){ $items=@(); foreach($n in ($xml -split '<node ')){ $m=[regex]::Match($n,'text="([^"]*)"'); if(!$m.Success -or $m.Groups[1].Value -ne $text){continue}; $b=[regex]::Match($n,'bounds="([^"]+)"'); if(!$b.Success){continue}; $r=[regex]::Match($b.Groups[1].Value,'\[(\d+),(\d+)\]\[(\d+),(\d+)\]'); if(!$r.Success){continue}; $x=[int](([int]$r.Groups[1].Value+[int]$r.Groups[3].Value)/2); $y=[int](([int]$r.Groups[2].Value+[int]$r.Groups[4].Value)/2); $items += [pscustomobject]@{x=$x;y=$y;top=[int]$r.Groups[2].Value} }; if(!$items.Count){return $false}; $p=if($bottom){$items|Sort-Object y -Descending|Select-Object -First 1}else{$items|Select-Object -First 1}; & $adb shell input tap $p.x $p.y; return $true }
& $adb shell am force-stop com.xiaoshouji.app; & $adb shell am start -n com.xiaoshouji.app/com.xiaoshouji.app.MainActivity | Out-Null; Start-Sleep -Seconds 4
$xml=Dump 'r144_start'; $steps=@()
$steps += [ordered]@{step='主应用启动';appForeground=(Focus);wechatOrMine=((Has $xml '微信') -or (Has $xml '我的'))}
$clicked=TapText $xml '我的' $true; Start-Sleep -Seconds 1; $xml=Dump 'r144_mine'; $steps += [ordered]@{step='切换我的';clicked=$clicked;appForeground=(Focus);personaLibrary=(Has $xml '用户人设库');wallet=(Has $xml '钱包')}
$clicked=TapText $xml '用户人设库'; Start-Sleep -Seconds 1; $xml=Dump 'r144_persona'; $steps += [ordered]@{step='打开用户人设库';clicked=$clicked;appForeground=(Focus);title=(Has $xml '用户人设库');add=(Has $xml '新增人设')}
& $adb shell input keyevent 4; Start-Sleep -Milliseconds 600; if(!(Focus)){ & $adb shell am start -n com.xiaoshouji.app/com.xiaoshouji.app.MainActivity | Out-Null; Start-Sleep -Seconds 2 }; $xml=Dump 'r144_mine_after'; if(-not (Has $xml '钱包')){ TapText $xml '我的' $true | Out-Null; Start-Sleep -Milliseconds 700; $xml=Dump 'r144_mine_after2' }
$clicked=TapText $xml '钱包'; Start-Sleep -Seconds 1; $xml=Dump 'r144_wallet'; $steps += [ordered]@{step='打开钱包';clicked=$clicked;appForeground=(Focus);title=(Has $xml '钱包');addBill=(Has $xml '记一笔')}
$clicked=TapText $xml '记一笔'; Start-Sleep -Seconds 1; $xml=Dump 'r144_bill'; $steps += [ordered]@{step='打开记一笔';clicked=$clicked;appForeground=(Focus);title=(Has $xml '钱包');form=((Has $xml '金额') -or (Has $xml '保存') -or (Has $xml '收入') -or (Has $xml '支出'))}
& $adb shell input keyevent 4; Start-Sleep -Milliseconds 500; & $adb shell am start -n com.xiaoshouji.app/com.xiaoshouji.app.MainActivity | Out-Null; Start-Sleep -Seconds 1; $xml=Dump 'r144_final'; $clicked=TapText $xml '消息' $true; Start-Sleep -Milliseconds 700; $xml=Dump 'r144_final2'; $steps += [ordered]@{step='回到微信消息';clicked=$clicked;appForeground=(Focus);wechatTitle=(Has $xml '微信');messages=(Has $xml '消息');contacts=(Has $xml '联系人');moments=(Has $xml '朋友圈');mine=(Has $xml '我的')}
$log=(& $adb logcat -d -t 400 | Select-String -Pattern 'FATAL EXCEPTION|ANR in|Fatal signal|Uncaught').Count
$out=[ordered]@{ok=(($steps|Where-Object{$_.appForeground -eq $false}).Count -eq 0 -and ($steps|Where-Object{$_.clicked -eq $false}).Count -eq 0 -and $log -eq 0);checkedAt=(Get-Date).ToString('o');device='OPPO PMK110';android='16';package='com.xiaoshouji.app';version='3.98';versionCode=109;steps=$steps;fatalAnrJsErrorCount=$log;dataCleared=$false;existingPersonasModified=$false;messagesSent=$false;browserUsed=$false}
$out|ConvertTo-Json -Depth 8|Set-Content -LiteralPath 'docs\testing\round144-device-clicks.json' -Encoding UTF8
$out|ConvertTo-Json -Depth 8
